import { migrationFiles } from './db.js';
import { seedSql } from './seed.js';

// One self-contained SQL script: every migration, the _migrations bookkeeping, and Season 1 data.
export function buildSetupSql() {
  const files = migrationFiles();
  return `-- Soul Runner NBA 2k27 PC Leagues: complete database setup.
-- Generated by \`npm run db:sql\`. Run once on an EMPTY PostgreSQL database.
-- (To update an existing database later, use \`npm run db:setup\` instead.)

BEGIN;

CREATE TABLE _migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());

${files.map(f => `-- ===== ${f.name} =====\n${f.sql.trim()}\n`).join('\n')}
INSERT INTO _migrations (name) VALUES ${files.map(f => `('${f.name}')`).join(', ')};

-- ===== Season 1 data =====
${seedSql()}
COMMIT;
`;
}
